  1	//go:build darwin
  2	
  3	// OQ-3 runner: executes the ledger, records every event, scores every delivery, writes the evidence.
  4	
  5	package cmd
  6	
  7	import (
  8		"crypto/sha256"
  9		"database/sql"
 10		"encoding/base64"
 11		"encoding/hex"
 12		"encoding/json"
 13		"fmt"
 14		"net/http"
 15		"os"
 16		"path/filepath"
 17		"sort"
 18		"strconv"
 19		"strings"
 20		"testing"
 21		"time"
 22	
 23		_ "github.com/mattn/go-sqlite3"
 24	)
 25	
 26	type oq3Event struct {
 27		Scenario string `json:"scenario"`
 28		Step     int    `json:"step"`
 29		Op       string `json:"op"`
 30		Class    string `json:"class"`
 31		Label    string `json:"label"`
 32		Trial    string `json:"trial,omitempty"`
 33		Verdict  string `json:"verdict"` // pass | fail | absent | done | harness-failed
 34		Outcome  any    `json:"outcome,omitempty"`
 35		At       string `json:"at"`
 36	}
 37	
 38	type oq3Run struct {
 39		t        *testing.T
 40		sc       oq3Scenario
 41		d        *oq3Daemon
 42		s        *oq3Sandbox
 43		desk     *oq3Desktop
 44		deskLife int
 45		term     *oq3Terminal
 46		termN    int
 47		convIDs  map[string]string
 48		async    map[string]chan asyncResult
 49		marks    map[string]int
 50		// marksLabel remembers which label a held turn was sent under, per conversation handle.
 51		marksLabel map[string]string
 52		// builtBinary, when set, is the built `ollama` used by the entry arm for CLI steps.
 53		builtBinary []string
 54		events      []oq3Event
 55		invalid     []string
 56	}
 57	
 58	func oq3NewRun(t *testing.T, sc oq3Scenario, d *oq3Daemon, s *oq3Sandbox) *oq3Run {
 59		return &oq3Run{t: t, sc: sc, d: d, s: s, convIDs: map[string]string{}, async: map[string]chan asyncResult{},
 60			marks: map[string]int{}, marksLabel: map[string]string{}}
 61	}
 62	
 63	type asyncResult struct {
 64		id  string
 65		res oq3HTTPResult
 66	}
 67	
 68	func oq3Label(sc string, i int, op string) string { return fmt.Sprintf("%s/%02d/%s", sc, i, op) }
 69	
 70	func (r *oq3Run) event(i int, st oq3Step, verdict string, outcome any) {
 71		r.events = append(r.events, oq3Event{Scenario: r.sc.ID, Step: i, Op: st.Op, Class: st.Class, Label: oq3Label(r.sc.ID, i, st.Op),
 72			Trial: st.Trial, Verdict: verdict, Outcome: outcome, At: time.Now().Format(time.RFC3339Nano)})
 73		if verdict == "harness-failed" {
 74			r.invalid = append(r.invalid, fmt.Sprintf("%s step %d %s: %v", r.sc.ID, i, st.Op, outcome))
 75		}
 76	}
 77	
 78	// execute runs every step. A harness failure stops the scenario (later steps are recorded as not
 79	// run) and makes the run invalid; it is never scored as a delivery defect.
 80	func (r *oq3Run) execute() {
 81		for i, st := range r.sc.Steps {
 82			label := oq3Label(r.sc.ID, i, st.Op)
 83			switch st.Op {
 84			case "terminal-await":
 85				// Requests caused while a held turn completes (its tool continuations) belong to that
 86				// turn, so its label stays active.
 87				r.d.setLabel(r.heldLabel("terminal"))
 88			case "desktop-await":
 89				r.d.setLabel(r.heldLabel(st.Args["conv"]))
 90			default:
 91				r.d.setLabel(label)
 92			}
 93			if len(r.invalid) > 0 {
 94				r.event(i, st, "not-run", "an earlier harness failure stopped this scenario")
 95				continue
 96			}
 97			func() {
 98				defer func() {
 99					if p := recover(); p != nil {
100						r.event(i, st, "harness-failed", fmt.Sprint(p))
101					}
102				}()
103				r.step(i, st, label)
104			}()
105		}
106		if r.term != nil {
107			r.term.kill()
108		}
109		if r.desk != nil {
110			_ = r.desk.cmd.Process.Kill()
111		}
112	}
113	
114	func (r *oq3Run) harnessFail(format string, a ...any) {
115		panic(fmt.Sprintf(format, a...))
116	}
117	
118	func (r *oq3Run) step(i int, st oq3Step, label string) {
119		switch st.Op {
120		case "desktop-start":
121			r.deskLife++
122			r.desk = oq3StartDesktopNoFatal(r, r.deskLife)
123			r.event(i, st, "done", map[string]any{"life": r.deskLife})
124		case "desktop-stop":
125			if err := r.desk.stopNoFatal(); err != nil {
126				r.harnessFail("desktop stop: %v", err)
127			}
128			r.event(i, st, "done", map[string]any{"life": r.deskLife, "exited": true})
129			r.desk = nil
130		case "auth-control":
131			unauth := r.desk.doAuth(http.MethodGet, "/api/v1/settings", nil, false)
132			auth := r.desk.doAuth(http.MethodGet, "/api/v1/settings", nil, true)
133			ok := unauth.Status == http.StatusForbidden && auth.Status == http.StatusOK && strings.Contains(auth.Body, `"settings"`)
134			if !ok {
135				r.harnessFail("auth control: unauthenticated %d, authenticated %d", unauth.Status, auth.Status)
136			}
137			r.event(i, st, "done", map[string]any{"unauthenticated": unauth.Status, "authenticated": auth.Status})
138		case "legacy-fixture":
139			id := "0192f0a0-3c3d-7000-8000-0000000000aa"
140			c := oq3HelperCmd(r.s, r.d, "legacy", "OQ3_CHAT_ID="+id)
141			out, err := c.CombinedOutput()
142			if err != nil {
143				r.harnessFail("legacy fixture: %v: %s", err, out)
144			}
145			r.convIDs[st.Args["conv"]] = id
146			r.event(i, st, "done", map[string]any{"chat_id": id})
147		case "desktop-save":
148			body := map[string]any{"expected_revision": st.Args["expected_revision"],
149				"edit": map[string]any{"enabled": st.Args["enabled"] == "true", "text": oq3TextOrEmpty(st.Args["text"]), "binding": nil}}
150			res := r.desk.do(http.MethodPut, "/api/v1/instructions", body)
151			verdict := oq3ProfileVerdict(res, st.Want)
152			if verdict == "pass" {
153				verdict = r.storeCommitted(st.Want)
154			}
155			r.event(i, st, verdict, res)
156		case "desktop-draft":
157			res := r.desk.do(http.MethodPost, "/api/v1/create-chat", map[string]any{})
158			var v struct {
159				ID string `json:"id"`
160			}
161			if res.Status != 200 || json.Unmarshal([]byte(res.Body), &v) != nil || v.ID == "" {
162				r.event(i, st, "fail", res)
163				r.harnessFail("create-chat did not return an id: %d %s", res.Status, res.Body)
164			}
165			r.convIDs[st.Conv] = v.ID
166			r.event(i, st, "pass", map[string]any{"status": res.Status, "chat_id": v.ID})
167		case "desktop-turn":
168			r.desktopTurn(i, st, label)
169		case "desktop-await":
170			ch := r.async[st.Args["conv"]]
171			r.d.release(r.heldLabel(st.Args["conv"]))
172			select {
173			case ar := <-ch:
174				r.convIDs[st.Args["conv"]] = ar.id
175				r.event(i, st, "done", map[string]any{"status": ar.res.Status})
176			case <-time.After(60 * time.Second):
177				r.harnessFail("held desktop turn never completed")
178			}
179		case "desktop-reload":
180			id := r.convIDs[st.Conv]
181			if id == "" {
182				r.harnessFail("reload of unknown conversation %q", st.Conv)
183			}
184			body := map[string]any{"expected_generation": st.Args["expected_generation"], "expected_target_revision": st.Args["expected_target_revision"]}
185			res := r.desk.do(http.MethodPost, "/api/v1/chat/"+id+"/instructions/reload", body)
186			r.event(i, st, oq3ReloadVerdict(res, st.Want), res)
187		case "cli-set":
188			path := filepath.Join(r.s.tmp, fmt.Sprintf("instructions-%s-%02d.txt", r.sc.ID, i))
189			if err := os.WriteFile(path, []byte(oq3TextOrEmpty(st.Args["text"])), 0o600); err != nil {
190				r.harnessFail("write instructions file: %v", err)
191			}
192			res := oq3RunCLINoFatal(r, "instructions", "set", "--file", path, "--expected-revision", st.Args["expected_revision"])
193			verdict := "fail"
194			switch {
195			case strings.Contains(res.Output, "unknown command"):
196				verdict = "absent"
197			case res.ExitCode == 0:
198				// Blueprint §7 as resolved in continuation 14: `set` saves the file's text as an
199				// enabled profile. Exit 0 counts only when the store shows it committed.
200				verdict = r.storeCommitted(map[string]string{"revision": st.Want["revision"], "enabled": "true", "text": st.Args["text"]})
201			}
202			r.event(i, st, verdict, res)
203		case "terminal-start":
204			r.termN++
205			r.term = oq3StartTerminalNoFatal(r, fmt.Sprintf("%s-%d", r.sc.ID, r.termN), st.Args["model"])
206			if !oq3WaitFor(30*time.Second, func() bool {
207				return r.d.countLabel("POST", "/api/generate", label) >= 1 || r.term.hasExited()
208			}) || r.term.hasExited() {
209				r.harnessFail("terminal session never preloaded; screen tail %q", tail(r.term.screen(), 1500))
210			}
211			r.mustQuiet("after the session started")
212			r.event(i, st, "done", map[string]any{"session": r.termN})
213		case "terminal-stop":
214			r.term.typeLine("/bye")
215			if err, ok := r.term.waitExit(20 * time.Second); !ok || err != nil {
216				r.harnessFail("terminal did not exit cleanly on /bye: ok=%v err=%v", ok, err)
217			}
218			r.event(i, st, "done", map[string]any{"session": r.termN, "exited": true})
219			r.term.kill()
220			r.term = nil
221		case "entry-start":
222			// The entry arm: the built `ollama` binary with no arguments, through the launcher menu
223			// (cmd/cmd.go:2161-2260) to the agent chat, exactly as the operator starts it.
224			if len(r.builtBinary) == 0 {
225				r.harnessFail("entry arm needs the built binary (OQ3_BINARY)")
226			}
227			r.termN++
228			r.term = oq3StartTerminalWith(oq3Panic, r.s, r.d, fmt.Sprintf("%s-%d", r.sc.ID, r.termN), "", r.builtBinary)
229			mark := 0
230			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(mark, "Chat, Code") || r.term.hasExited() }) || r.term.hasExited() {
231				r.harnessFail("launcher menu never appeared; screen tail %q", tail(r.term.screen(), 1500))
232			}
233			r.term.quiet(500*time.Millisecond, 10*time.Second)
234			mark = r.term.rawLen()
235			r.term.key("\r")
236			if !oq3WaitFor(30*time.Second, func() bool {
237				return r.term.screenContainsAfter(mark, "Select model") || r.d.countLabel("POST", "/api/generate", label) >= 1 || r.term.hasExited()
238			}) || r.term.hasExited() {
239				r.harnessFail("the run-model action reached neither a model picker nor the chat; screen tail %q", tail(r.term.screen(), 1500))
240			}
241			picked := false
242			if r.d.countLabel("POST", "/api/generate", label) == 0 {
243				r.term.quiet(400*time.Millisecond, 10*time.Second)
244				r.term.key(oq3Model)
245				r.term.quiet(400*time.Millisecond, 10*time.Second)
246				r.term.key("\r")
247				picked = true
248			}
249			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/generate", label) >= 1 || r.term.hasExited() }) || r.term.hasExited() {
250				r.harnessFail("the agent chat never preloaded after the launcher; screen tail %q", tail(r.term.screen(), 1500))
251			}
252			r.term.quiet(700*time.Millisecond, 15*time.Second)
253			r.event(i, st, "done", map[string]any{"session": r.termN, "model_picker_used": picked, "binary": r.builtBinary[0]})
254		case "entry-stop":
255			mark := r.term.rawLen()
256			r.term.typeLine("/bye")
257			if !oq3WaitFor(20*time.Second, func() bool { return r.term.screenContainsAfter(mark, "Chat, Code") || r.term.hasExited() }) {
258				r.harnessFail("the launcher menu did not return after /bye; screen tail %q", tail(r.term.screen(), 1500))
259			}
260			if !r.term.hasExited() {
261				r.term.quiet(400*time.Millisecond, 10*time.Second)
262				r.term.key("q")
263			}
264			if err, ok := r.term.waitExit(20 * time.Second); !ok || err != nil {
265				r.harnessFail("the launcher did not exit cleanly: ok=%v err=%v", ok, err)
266			}
267			r.event(i, st, "done", map[string]any{"session": r.termN, "exited": true})
268			r.term.kill()
269			r.term = nil
270		case "terminal-turn":
271			r.terminalTurn(i, st, label)
272		case "terminal-await":
273			lbl := r.heldLabel("terminal")
274			mark := r.marks["terminal"]
275			r.d.release(lbl)
276			r.finishTerminalTurn(lbl, r.marks["terminal-rounds"], 0, mark)
277			r.event(i, st, "done", nil)
278		case "terminal-slash":
279			r.terminalSlash(i, st, label)
280		case "store-identity":
281			r.event(i, st, r.storeIdentity(st.Want), nil)
282		case "store-events":
283			r.event(i, st, r.storeEvents(), nil)
284		default:
285			r.harnessFail("unknown op %q", st.Op)
286		}
287	}
288	
289	func (r *oq3Run) heldLabel(conv string) string { return r.marksLabel[conv] }
290	
291	func oq3TextOrEmpty(key string) string {
292		if key == "" {
293			return ""
294		}
295		return oq3Texts[key]
296	}
297	
298	// ---------------------------------------------------------------------------------------------
299	// Desktop turns.
300	
301	func (r *oq3Run) desktopTurn(i int, st oq3Step, label string) {
302		id := r.convIDs[st.Conv]
303		if id == "" {
304			id = "new"
305		}
306		body := map[string]any{"model": oq3Model, "prompt": st.Prompt}
307		if m := st.Args["model"]; m != "" {
308			body["model"] = m
309		}
310		if st.Args["think"] == "true" {
311			body["think"] = true
312		}
313		if st.Args["web_search"] == "true" {
314			body["web_search"] = true
315		}
316		if name := st.Args["attachment"]; name != "" {
317			body["attachments"] = []any{map[string]any{"filename": name, "data": base64.StdEncoding.EncodeToString([]byte("OQ3 attachment line one.\nOQ3 attachment line two.\n"))}}
318		}
319		if s := st.Args["fail"]; s != "" {
320			n, _ := strconv.Atoi(s)
321			r.d.failNext(label, n)
322		}
323		if st.Args["hold"] == "1" {
324			r.d.hold(label)
325			r.marksLabel[st.Conv] = label
326			ch := make(chan asyncResult, 1)
327			r.async[st.Conv] = ch
328			desk := r.desk
329			go func() {
330				newID, res := desk.chatBody(id, body)
331				ch <- asyncResult{id: newID, res: res}
332			}()
333			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
334				r.harnessFail("held desktop turn never reached the daemon")
335			}
336			r.event(i, st, "dispatched-held", map[string]any{"conversation": st.Conv})
337			return
338		}
339		newID, res := r.desk.chatBody(id, body)
340		if newID != "" && newID != "new" {
341			r.convIDs[st.Conv] = newID
342		}
343		r.event(i, st, "done", map[string]any{"status": res.Status, "chat_id": newID, "stream_tail": tail(res.Body, 400)})
344	}
345	
346	// ---------------------------------------------------------------------------------------------
347	// Terminal turns and commands.
348	
349	func (r *oq3Run) terminalTurn(i int, st oq3Step, label string) {
350		rounds, _ := strconv.Atoi(st.Args["tool_rounds"])
351		if rounds > 0 {
352			r.d.setToolRounds(label, rounds)
353		}
354		if st.Args["auto_compact"] == "1" {
355			r.d.reportPromptEval(label, 30000)
356		}
357		mark := r.term.rawLen()
358		if st.Args["hold"] == "1" {
359			r.d.hold(label)
360			r.marksLabel["terminal"] = label
361			r.marks["terminal"] = mark
362		}
363		r.term.typeLine(st.Prompt)
364		if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
365			// No request reached the daemon: recorded, and scored by the step's class (a missing
366			// required delivery, or a refusal held as required).
367			r.mustQuiet("after a turn that sent no request")
368			r.event(i, st, "no-request", map[string]any{"screen_tail": tail(r.term.screen(), 1200)})
369			return
370		}
371		if st.Args["hold"] == "1" {
372			r.marks["terminal-rounds"] = rounds
373			r.event(i, st, "dispatched-held", nil)
374			return
375		}
376		r.finishTerminalTurn(label, rounds, st.Summarisers, mark)
377		r.event(i, st, "done", nil)
378	}
379	
380	// finishTerminalTurn approves each declared tool round, then waits until every response under the
381	// label has been fully written by the daemon and the screen has gone quiet (review finding 8).
382	func (r *oq3Run) finishTerminalTurn(label string, rounds, summarisers, mark int) {
383		for k := 0; k < rounds; k++ {
384			approvalMark := mark
385			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(approvalMark, "Approve once") }) {
386				r.harnessFail("tool round %d: approval prompt never appeared; screen tail %q", k+1, tail(r.term.screen(), 1500))
387			}
388			want := r.d.countLabel("POST", "/api/chat", label) + 1
389			mark = r.term.rawLen()
390			r.term.key("1")
391			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= want }) {
392				r.harnessFail("tool round %d: continuation never reached the daemon", k+1)
393			}
394		}
395		if !oq3WaitFor(30*time.Second, func() bool {
396			n := r.d.countLabel("POST", "/api/chat", label)
397			return r.d.countSummaries(label) >= summarisers && r.d.completedLabel(label) >= n
398		}) {
399			r.harnessFail("responses under %s never completed (%d requests, %d completed, %d summaries)", label,
400				r.d.countLabel("POST", "/api/chat", label), r.d.completedLabel(label), r.d.countSummaries(label))
401		}
402		r.mustQuiet("after the turn completed")
403	}
404	
405	// mustQuiet waits for the terminal to stop producing output; a timeout is a harness failure, never
406	// a reason to advance (review finding 8).
407	func (r *oq3Run) mustQuiet(when string) {
408		if !r.term.quiet(600*time.Millisecond, 20*time.Second) {
409			r.harnessFail("terminal did not go quiet %s; screen tail %q", when, tail(r.term.screen(), 800))
410		}
411	}
412	
413	func (r *oq3Run) terminalSlash(i int, st oq3Step, label string) {
414		cmd := st.Args["cmd"]
415		mark := r.term.rawLen()
416		if pick := st.Args["pick"]; pick != "" {
417			r.term.typeLine(cmd)
418			if !oq3WaitFor(15*time.Second, func() bool { return r.term.screenContainsAfter(mark, pick) }) {
419				r.harnessFail("model picker never listed %s; screen tail %q", pick, tail(r.term.screen(), 1500))
420			}
421			r.term.quiet(400*time.Millisecond, 10*time.Second)
422			r.term.key(pick)
423			r.term.quiet(400*time.Millisecond, 10*time.Second)
424			r.term.key("\r")
425			r.term.quiet(700*time.Millisecond, 15*time.Second)
426			r.event(i, st, "done", map[string]any{"picked": pick, "screen_tail": tail(r.term.screen(), 600)})
427			return
428		}
429		r.term.typeLine(cmd)
430		if st.Class == "required-refusal" {

431			// Sent while a held turn runs: the screen only animates, so nothing on it can show the
432			// refusal. Its effect is judged by the held turn's own continuation, which must keep the
433			// old revision (review finding 1). No wait: the turn is still running.
434			r.event(i, st, "sent-while-running", nil)
435			return
436		}
437		if st.Summarisers > 0 {
438			if !oq3WaitFor(30*time.Second, func() bool {
439				return r.d.countSummaries(label) >= st.Summarisers && r.d.completedLabel(label) >= r.d.countLabel("POST", "/api/chat", label)
440			}) {
441				r.mustQuiet("after a compaction that did not complete")
442				r.event(i, st, "fail", map[string]any{"summarisers_seen": r.d.countSummaries(label), "screen_tail": tail(r.term.screen(), 1200)})
443				return
444			}
445		}
446		r.mustQuiet("after " + cmd)
447		unknown := r.term.screenContainsAfter(mark, "Unknown command") || r.term.screenContainsAfter(mark, "usage: ")
448		verdict := "done"
449		switch {
450		case unknown && strings.HasPrefix(cmd, "/instructions"):
451			verdict = "absent"
452		case unknown:
453			// An existing command that printed an error or its usage did not do what the step declares.
454			r.harnessFail("%s was rejected by the terminal; screen tail %q", cmd, tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600))
455		case strings.HasPrefix(cmd, "/instructions"):
456			// No error was printed. The blueprint (§7) names no success output, so the screen cannot
457			// show success; the delivery after this step decides (review finding 1).
458			verdict = "no-error-seen"
459		}
460		r.event(i, st, verdict, map[string]any{"screen_tail": tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600)})
461	}
462	
463	// ---------------------------------------------------------------------------------------------
464	// Operation verdicts. "absent" means the designated surface does not exist at this commit (the
465	// application's HTML fallback or an unknown command); it is a failed operation, not a harness fault.
466	
467	func oq3IsHTML(res oq3HTTPResult) bool {
468		return strings.Contains(strings.ToLower(res.ContentType), "text/html") || strings.HasPrefix(strings.TrimSpace(strings.ToLower(res.Body)), "<!doctype html")
469	}
470	
471	func oq3ProfileVerdict(res oq3HTTPResult, want map[string]string) string {
472		if oq3IsHTML(res) || res.Status == http.StatusNotFound {
473			return "absent"
474		}
475		var p struct {
476			Revision string `json:"revision"`
477			Enabled  bool   `json:"enabled"`
478			Text     string `json:"text"`
479		}
480		if res.Status != 200 || json.Unmarshal([]byte(res.Body), &p) != nil {
481			return "fail"
482		}
483		if p.Revision != want["revision"] || fmt.Sprint(p.Enabled) != want["enabled"] || p.Text != oq3TextOrEmpty(want["text"]) {
484			return "fail"
485		}
486		return "pass"
487	}
