489	func oq3ReloadVerdict(res oq3HTTPResult, want map[string]string) string {
490		if oq3IsHTML(res) || res.Status == http.StatusNotFound {
491			return "absent"
492		}
493		if fmt.Sprint(res.Status) != want["status"] {
494			return "fail"
495		}
496		if want["code"] != "" {
497			var e struct {
498				Error struct {
499					Code string `json:"code"`
500				} `json:"error"`
501			}
502			if json.Unmarshal([]byte(res.Body), &e) != nil || e.Error.Code != want["code"] {
503				return "fail"
504			}
505			return "pass"
506		}
507		var sel struct {
508			Revision   string `json:"revision"`
509			Generation string `json:"generation"`
510		}
511		if json.Unmarshal([]byte(res.Body), &sel) != nil || sel.Revision != want["revision"] || sel.Generation != want["generation"] {
512			return "fail"
513		}
514		return "pass"
515	}
