521	// storeCommitted reads the designated store's current profile (blueprint §3.1 schema) read-only:
522	// "absent" before G1, "pass" when it holds the expected revision, enabled flag and text (review
523	// finding 10: an exit status or a response body alone is not a committed save).
524	func (r *oq3Run) storeCommitted(want map[string]string) string {
525		if _, err := os.Stat(r.storePath()); err != nil {
526			return "absent"
527		}
528		db, err := sql.Open("sqlite3", "file:"+r.storePath()+"?mode=ro")
529		if err != nil {
530			return "fail"
531		}
532		defer db.Close()
533		var rev int64
534		var enabled int
535		var text string
536		if err := db.QueryRow(`SELECT m.current_revision, r.enabled, r.text FROM metadata m JOIN revisions r ON r.revision = m.current_revision WHERE m.id = 1`).Scan(&rev, &enabled, &text); err != nil {
537			return "fail"
538		}
539		if fmt.Sprint(rev) == want["revision"] && fmt.Sprint(enabled == 1) == want["enabled"] && text == oq3TextOrEmpty(want["text"]) {
540			return "pass"
541		}
542		return "fail"
543	}
