545	// storeEvents checks the terminal event sequence of blueprint §3.1: two conversations opened under
546	// distinct identities, and one reload recorded under the SECOND identity, from revision 2 to 3 at
547	// generation 2 (review finding 11: a new binding the runtime never uses would leave the reload on
548	// the first identity).
549	func (r *oq3Run) storeEvents() string {
550		if _, err := os.Stat(r.storePath()); err != nil {
551			return "absent"
552		}
553		db, err := sql.Open("sqlite3", "file:"+r.storePath()+"?mode=ro")
554		if err != nil {
555			return "fail"
556		}
557		defer db.Close()
558		rows, err := db.Query(`SELECT conversation_id, generation, kind, COALESCE(from_revision, -1), to_revision FROM events WHERE namespace = 'terminal' ORDER BY rowid`)
559		if err != nil {
560			return "fail"
561		}
562		defer rows.Close()
563		type ev struct {
564			id         string
565			gen        int
566			kind       string
567			from, to   int
568		}
569		var evs []ev
570		for rows.Next() {
571			var e ev
572			if err := rows.Scan(&e.id, &e.gen, &e.kind, &e.from, &e.to); err != nil {
573				return "fail"
574			}
575			evs = append(evs, e)
576		}
577		var opened []ev
578		var reloaded []ev
579		for _, e := range evs {
580			switch e.kind {
581			case "opened":
582				opened = append(opened, e)
583			case "reloaded":
584				reloaded = append(reloaded, e)
585			}
586		}
587		if len(opened) != 2 || len(reloaded) != 1 || opened[0].id == opened[1].id {
588			return "fail"
589		}
590		rl := reloaded[0]
591		if rl.id != opened[1].id || rl.gen != 2 || rl.from != 2 || rl.to != 3 || opened[0].to != 1 || opened[1].to != 2 {
592			return "fail"
593		}
594		return "pass"
595	}
