598	// conversation identities. Before G1 the store does not exist, which is reported as absent.
599	func (r *oq3Run) storeIdentity(want map[string]string) string {
600		path := filepath.Join(r.s.home, ".ollama", "instructions", "instructions.sqlite")
601		if _, err := os.Stat(path); err != nil {
602			return "absent"
603		}
604		db, err := sql.Open("sqlite3", "file:"+path+"?mode=ro")
605		if err != nil {
606			return "fail"
607		}
608		defer db.Close()
609		var n int
610		if err := db.QueryRow(`SELECT COUNT(DISTINCT conversation_id) FROM conversations WHERE namespace = 'terminal'`).Scan(&n); err != nil {
611			return "fail"
612		}
613		min, _ := strconv.Atoi(want["min_terminal"])
614		if n >= min {
615			return "pass"
616		}
617		return "fail"
618	}
