664	// oq3KnownPaths are the daemon endpoints the entry points are known to call. Anything else is an
665	// unclassified request and makes the run invalid (review finding 4).
666	var oq3KnownPaths = map[string]bool{"/": true, "/api/version": true, "/api/show": true, "/api/tags": true, "/api/ps": true,
667		"/api/generate": true, "/api/chat": true, "/api/status": true, "/api/me": true, "/api/pull": true,
