670	// score attributes every captured request to the step that caused it and scores it.
671	// freeze: when a golden is absent, the observed pre-G1 request becomes the golden (baseline only).
672	func (r *oq3Run) score(goldenDir string, freeze bool, source string) oq3ScenarioResult {
673		res := oq3ScenarioResult{Scenario: r.sc, Events: r.events, Invalid: append([]string(nil), r.invalid...), Sandbox: r.s.root}
674		caps := r.d.snapshot()
675		res.Captures = caps
676		notRun := map[int]bool{}
677		lastHeld := -1
678		for _, e := range r.events {
679			if e.Verdict == "dispatched-held" {
680				lastHeld = e.Step
681			}
682			if e.Verdict == "not-run" || e.Verdict == "harness-failed" {
683				notRun[e.Step] = true
684				// A held turn whose completion failed was not measured either.
685				if (e.Op == "terminal-await" || e.Op == "desktop-await") && lastHeld >= 0 {
686					notRun[lastHeld] = true
687				}
688			}
689		}
690		type key struct {
691			label, path string
692		}
693		byKey := map[key][]oq3Capture{}
694		for _, c := range caps {
695			if !oq3KnownPaths[c.Path] {
696				res.Invalid = append(res.Invalid, fmt.Sprintf("unclassified request %s %s under %q", c.Method, c.Path, c.Label))
697			}
698			byKey[key{c.Label, c.Path}] = append(byKey[key{c.Label, c.Path}], c)
699		}
700		known := map[string]bool{}
701		scoredSeq := map[int]bool{} // /api/chat captures scored as conversation deliveries
702		loadOrFreeze := func(gp string, gf oq3GoldenFile, obs any) (any, error) {
703			golden, err := oq3LoadGolden(gp)
704			if err == nil {
705				return golden, nil
706			}
707			if !freeze {
708				return nil, err
709			}
710			gf.Request = obs
711			gf.Source = source
712			if werr := oq3WriteJSON(gp, gf); werr != nil {
713				r.t.Fatalf("write golden: %v", werr)
714			}
715			return obs, nil
716		}
717		aux := func(d oq3Delivery) { res.Auxiliary = append(res.Auxiliary, d) }
718		for i, st := range r.sc.Steps {
719			label := oq3Label(r.sc.ID, i, st.Op)
720			known[label] = true
721			if notRun[i] {
722				res.NotMeasured = append(res.NotMeasured, fmt.Sprintf("%s (%s)", label, st.Trial))
723				continue
724			}
725			var turns, sums []oq3Capture
726			for _, c := range byKey[key{label, "/api/chat"}] {
727				if c.Response == "summary" {
728					sums = append(sums, c)
729				} else {
730					turns = append(turns, c)
731				}
732			}
733			// Summariser requests: allowed only where the step declares them, exactly that many, each
734			// equal to its frozen pre-G1 golden (review findings 2 and 3).
735			if len(sums) != st.Summarisers {
736				if st.Summarisers > 0 && len(sums) < st.Summarisers {
737					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: compaction did not happen (%d summariser requests, %d declared)", label, len(sums), st.Summarisers))
738				}
739				if len(sums) > st.Summarisers {
740					aux(oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Status: "bad",
741						Verdict: oq3DeliveryVerdict{Categories: []string{"undeclared-summariser"}, Detail: fmt.Sprintf("%d summariser requests, %d declared", len(sums), st.Summarisers)}})
742				}
743			}
744			for k, c := range sums {
745				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k, Seq: c.Seq, Kind: "summariser"}
746				obs, err := oq3Normalise(c.Body, r.s.root)
747				if err != nil {
748					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}}
749					aux(d)
750					continue
751				}
752				gp := filepath.Join(goldenDir, r.sc.ID, fmt.Sprintf("%02d-s%d.json", i, k))
753				d.Golden = gp
754				golden, gerr := loadOrFreeze(gp, oq3GoldenFile{Scenario: r.sc.ID, Step: i, Index: k, Label: label, Trial: st.Trial, Kind: "summariser"}, obs)
755				if gerr != nil {
756					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"no-golden"}}
757					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: no summariser golden %s", label, gp))
758					aux(d)
759					continue
760				}
761				d.Verdict = oq3Unchanged(obs, golden)
762				if v := oq3CheckSummariser(obs); !v.Correct {
763					d.Verdict.Correct = false
764					d.Verdict.Categories = append(d.Verdict.Categories, v.Categories...)
765				}
766				d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
767				aux(d)
768			}
769			// Preloads: each equal to its frozen pre-G1 golden (review finding 4).
770			for k, c := range byKey[key{label, "/api/generate"}] {
771				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k, Seq: c.Seq, Kind: "preload"}
772				obs, err := oq3Normalise(c.Body, r.s.root)
773				if err != nil {
774					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}}
775					aux(d)
776					continue
777				}
778				gp := filepath.Join(goldenDir, r.sc.ID, fmt.Sprintf("%02d-g%d.json", i, k))
779				d.Golden = gp
780				golden, gerr := loadOrFreeze(gp, oq3GoldenFile{Scenario: r.sc.ID, Step: i, Index: k, Label: label, Trial: st.Trial, Kind: "preload"}, obs)
781				if gerr != nil {
782					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"no-golden"}}
783					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: no preload golden %s", label, gp))
784					aux(d)
785					continue
786				}
787				d.Verdict = oq3Unchanged(obs, golden)
788				d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
789				aux(d)
790			}
791			switch st.Class {
792			case "required-no-dispatch":
793				// A refusal is required: any model request under this step is an incorrect delivery.
794				if len(turns) == 0 {
795					res.Deliveries = append(res.Deliveries, oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial,
796						Status: "refused-as-required", Verdict: oq3DeliveryVerdict{Correct: true}})
797				}
798				for k, c := range turns {
799					scoredSeq[c.Seq] = true
800					res.Deliveries = append(res.Deliveries, oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k, Seq: c.Seq,
801						Status: "bad", Verdict: oq3DeliveryVerdict{Categories: []string{"dispatched-despite-required-refusal"}}})
802				}
803				continue
804			case "required-dispatch":
805			default:
806				if len(turns) > 0 {
807					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: %d unclassified model requests under a non-dispatch step", label, len(turns)))
808				}
809				continue
810			}
811			for k := 0; k < len(st.Expect) || k < len(turns); k++ {
812				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k}
813				if k < len(st.Expect) {
814					e := st.Expect[k]
815					d.Expect = &e
816				}
817				if k >= len(turns) {
818					d.Status = "missing"
819					d.Verdict = oq3DeliveryVerdict{Categories: []string{"not-dispatched"}}
820					res.Deliveries = append(res.Deliveries, d)
821					continue
822				}
823				c := turns[k]
824				d.Seq = c.Seq
825				scoredSeq[c.Seq] = true
826				obs, err := oq3Normalise(c.Body, r.s.root)
827				if err != nil {
828					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}, Detail: err.Error()}
829					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: malformed capture %d", label, c.Seq))
830					res.Deliveries = append(res.Deliveries, d)
831					continue
832				}
833				if d.Expect == nil {
834					d.Status = "unexpected"
835					d.Verdict = oq3DeliveryVerdict{Categories: []string{"unexpected-request"}}
836					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: more model requests than declared (%d > %d)", label, len(turns), len(st.Expect)))
837					res.Deliveries = append(res.Deliveries, d)
838					continue
839				}
840				gp := oq3GoldenPath(goldenDir, r.sc.ID, i, k)
841				d.Golden = gp
842				golden, gerr := loadOrFreeze(gp, oq3GoldenFile{Scenario: r.sc.ID, Step: i, Index: k, Label: label, Trial: st.Trial, Expect: *d.Expect, Kind: "delivery"}, obs)
843				if gerr != nil {
844					d.Status = "bad"
845					d.Verdict = oq3DeliveryVerdict{Categories: []string{"no-golden"}, Detail: gerr.Error()}
846					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: no golden %s", label, gp))
847					res.Deliveries = append(res.Deliveries, d)
848					continue
849				}
