  3	// OQ-3 oracle: what a correct delivery looks like, derived independently of the code under test.
  4	//
  5	// The expected request for every delivery is built from two inputs only: the request the unchanged
  6	// (pre-G1) candidate sent for the same step, frozen as a golden, and the composition rule of the G1
  7	// blueprint §5 (docs/_design/G1_PERSISTED_INSTRUCTIONS.md:200-206) implemented here from its text.
  8	// No production composition code is called. The admission field is §6.3 A1 (version 1).
  9	
 10	package cmd
 11	
 12	import (
 13		"bytes"
 14		"encoding/json"
 15		"fmt"
 16		"path/filepath"
 17		"reflect"
 18		"regexp"
 19		"sort"
 20		"strings"
 21	)
 22	
 23	// oq3Unchanged is the expectation for auxiliary model traffic that G1 must leave exactly as it was
 24	// (a compaction summariser request, a preload): equal to its frozen pre-G1 golden. When it is not,
 25	// it names whether instructions leaked into it.
 26	func oq3Unchanged(observed, golden any) oq3DeliveryVerdict {
 27		if reflect.DeepEqual(observed, golden) {
 28			return oq3DeliveryVerdict{Correct: true}
 29		}
 30		var cats []string
 31		b, _ := json.Marshal(observed)
 32		if bytes.Contains(b, []byte("User-configured instructions")) {
 33			cats = append(cats, "carries-header")
 34		}
 35		for _, s := range oq3AllSentinels {
 36			if bytes.Contains(b, []byte(s)) {
 37				cats = append(cats, "carries-profile")
 38				break
 39			}
 40		}
 41		cats = append(cats, "request-changed")
 42		return oq3DeliveryVerdict{Categories: cats, Detail: oq3FirstDifference(observed, golden)}
 43	}
 44	
 45	// oq3Texts are the contrasting instruction profiles. Each carries sentinels at its start, middle and
 46	// end, a line break and a non-ASCII character, so truncation, re-encoding or partial loss is visible.
 47	var oq3Texts = map[string]string{
 48		"A": "SENTINEL-A-START-5d2c OQ3 instruction profile A: answer in Australian English and keep replies short.\n" +
 49			"SENTINEL-A-MID-9e41 Name the café you would recommend — this line checks bytes beyond ASCII.\n" +
 50			"Close every reply with the word ALPHA. SENTINEL-A-END-b7f0",
 51		"B": "SENTINEL-B-START-2a6e OQ3 instruction profile B: answer as a checklist of numbered steps.\n" +
 52			"SENTINEL-B-MID-4c18 Prefer metric units — naïve estimates are acceptable here.\n" +
 53			"Close every reply with the word BRAVO. SENTINEL-B-END-83d9",
 54	}
 55	
 56	// oq3AllSentinels lists every profile sentinel; none may appear anywhere a carrier is not expected.
 57	var oq3AllSentinels = []string{"SENTINEL-A-START-5d2c", "SENTINEL-A-MID-9e41", "SENTINEL-A-END-b7f0",
 58		"SENTINEL-B-START-2a6e", "SENTINEL-B-MID-4c18", "SENTINEL-B-END-83d9"}
 59	
 60	const oq3HeaderPrefix = "User-configured instructions; revision "
 61	
 62	func oq3Header(rev, gen int) string {
 63		return fmt.Sprintf("User-configured instructions; revision %d; selection %d:\n", rev, gen)
 64	}
 65	
 66	var oq3HeaderRE = regexp.MustCompile(`User-configured instructions; revision ([0-9]+); selection ([0-9]+):\n`)
 67	
 68	// oq3Expect is one required delivery's expectation.
 69	type oq3Expect struct {
 70		Carrier bool   `json:"carrier"`
 71		Rev     int    `json:"revision,omitempty"`
 72		Gen     int    `json:"generation,omitempty"`
 73		Text    string `json:"text,omitempty"` // key into oq3Texts
 74		// Adapter decides where the base comes from: "desktop" (model-system text of the request's model,
 75		// §5) or "terminal" (the system message the pre-G1 candidate sent, which is the built-in base).
 76		Adapter string `json:"adapter"`
 77	}
