 79	// ---------------------------------------------------------------------------------------------
 80	// Normalisation: only declared variable inputs are parameterised (Method 04 T-07).
 81	
 82	var (
 83		oq3DateRE = regexp.MustCompile(`Current date: [A-Z][a-z]+, [A-Z][a-z]+ [0-9]{1,2}, [0-9]{4}\.`)
 84	)
 85	
 86	// oq3Normalise decodes a request body and replaces declared variable text: the terminal prompt's
 87	// date line and the sandbox root path. Numbers stay exact (json.Number).
 88	func oq3Normalise(body []byte, sandboxRoot string) (any, error) {
 89		dec := json.NewDecoder(bytes.NewReader(body))
 90		dec.UseNumber()
 91		var v any
 92		if err := dec.Decode(&v); err != nil {
 93			return nil, err
 94		}
 95		if dec.More() {
 96			return nil, fmt.Errorf("more than one JSON value")
 97		}
 98		// The sandbox is spelt two ways on macOS (/var/... and its resolved /private/var/...); the
 99		// resolved spelling is replaced first so no machine-dependent prefix survives (review finding 7).
100		var roots []string
101		if sandboxRoot != "" {
102			if resolved, err := filepath.EvalSymlinks(sandboxRoot); err == nil && resolved != sandboxRoot {
103				roots = append(roots, resolved)
104			}
105			roots = append(roots, sandboxRoot)
106		}
107		return oq3Walk(v, func(s string) string {
108			s = oq3DateRE.ReplaceAllString(s, "Current date: <DATE>.")
109			for _, r := range roots {
110				s = strings.ReplaceAll(s, r, "<SANDBOX>")
111			}
112			return s
113		}), nil
114	}
