116	// oq3AdmitReserve accepts an admission object that §6.3 A1-A2 permit for a local request: version
117	// 1 and, optionally, a reserve that is non-negative and at most half the effective context (the
118	// fixture's context is 32768). It returns false for anything else (review finding 6).
119	func oq3AdmitReserve(adm any) bool {
120		m, ok := adm.(map[string]any)
121		if !ok {
122			return false
123		}
124		for k := range m {
125			if k != "version" && k != "reserve" {
126				return false
127			}
128		}
129		if v, ok := m["version"].(json.Number); !ok || v.String() != "1" {
130			return false
131		}
132		if r, ok := m["reserve"]; ok {
133			n, isNum := r.(json.Number)
134			if !isNum {
135				return false
136			}
137			iv, err := n.Int64()
138			if err != nil || iv < 0 || iv > 16384 {
139				return false
140			}
141		}
142		return true
143	}
144	
145	func oq3Walk(v any, f func(string) string) any {
146		switch x := v.(type) {
147		case map[string]any:
148			out := make(map[string]any, len(x))
149			for k, val := range x {
150				out[k] = oq3Walk(val, f)
151			}
152			return out
153		case []any:
154			out := make([]any, len(x))
155			for i, val := range x {
156				out[i] = oq3Walk(val, f)
157			}
158			return out
159		case string:
160			return f(x)
161		default:
162			return v
163		}
164	}
165	
166	func oq3DeepCopy(v any) any {
167		return oq3Walk(v, func(s string) string { return s })
168	}
169	
170	func oq3Messages(req any) []map[string]any {
171		m, _ := req.(map[string]any)
172		raw, _ := m["messages"].([]any)
173		out := make([]map[string]any, 0, len(raw))
174		for _, r := range raw {
175			if mm, ok := r.(map[string]any); ok {
176				out = append(out, mm)
177			}
178		}
179		return out
180	}
