253	// ---------------------------------------------------------------------------------------------
254	// Scoring one observed delivery.
255	
256	type oq3DeliveryVerdict struct {
257		Correct    bool     `json:"correct"`
258		Categories []string `json:"categories,omitempty"`
259		Detail     string   `json:"detail,omitempty"`
260	}
261	
262	// oq3Score compares one observed request (normalised) with the expected request, and when they
263	// differ, names every category of difference it can identify. An observed request that differs is
264	// one bad delivery, however many categories it has.
265	func oq3Score(observed, expected any, e oq3Expect) oq3DeliveryVerdict {
266		cats := map[string]bool{}
267		// A permitted reserve in the observed admission object is not a difference (finding 6); an
268		// admission object outside A1-A2 is its own category.
269		if om, ok := observed.(map[string]any); ok {
270			if em, ok := expected.(map[string]any); ok {
271				if oa, has := om["admission"]; has {
272					if _, want := em["admission"]; want {
273						if oq3AdmitReserve(oa) {
274							em = oq3DeepCopy(em).(map[string]any)
275							em["admission"] = oq3DeepCopy(oa)
276							expected = em
277						} else {
278							cats["admission-invalid"] = true
279						}
280					}
281				}
282			}
283		}
284		if len(cats) == 0 && reflect.DeepEqual(observed, expected) {
285			return oq3DeliveryVerdict{Correct: true}
286		}
287		var notes []string
288		obsMsgs := oq3Messages(observed)
289		expMsgs := oq3Messages(expected)
290	
291		// Where do carrier headers occur in the observed request?
292		type hit struct {
293			msg, rev, gen int
294			role          string
295		}
296		var hits []hit
297		for i, msg := range obsMsgs {
298			for _, mm := range oq3HeaderRE.FindAllStringSubmatch(oq3Str(msg, "content"), -1) {
299				var r, g int
300				fmt.Sscan(mm[1], &r)
301				fmt.Sscan(mm[2], &g)
302				hits = append(hits, hit{msg: i, rev: r, gen: g, role: oq3Str(msg, "role")})
303			}
304		}
305		obsJSON, _ := json.Marshal(observed)
306		om, _ := observed.(map[string]any)
307		_, hasAdmission := om["admission"]
308	
309		if e.Carrier {
310			text := oq3Texts[e.Text]
311			switch {
312			case len(hits) == 0:
313				cats["missing"] = true
314			case len(hits) > 1:
315				cats["duplicated"] = true
316			default:
317				h := hits[0]
318				if h.rev != e.Rev || h.gen != e.Gen {
319					cats["wrong-revision"] = true
320					notes = append(notes, fmt.Sprintf("header revision %d selection %d, expected %d/%d", h.rev, h.gen, e.Rev, e.Gen))
321				}
322				if h.msg != 0 || h.role != "system" {
323					cats["misplaced"] = true
324				}
325				content := oq3Str(obsMsgs[h.msg], "content")
326				idx := strings.Index(content, oq3HeaderPrefix)
327				if idx < 0 {
328					cats["other"] = true
329					break
330				}
331				after := content[idx:]
332				if loc := oq3HeaderRE.FindStringIndex(after); loc != nil {
333					after = after[loc[1]:]
334				}
335				if after != text {
336					cats["altered"] = true
337				}
338				if len(expMsgs) > 0 {
339					expContent := oq3Str(expMsgs[0], "content")
340					if ei := strings.Index(expContent, oq3HeaderPrefix); ei >= 0 && content[:idx] != expContent[:ei] {
341						cats["base-lost"] = true
342					}
343				}
344			}
345			if !hasAdmission {
346				cats["admission-missing"] = true
347			}
348		} else {
349			if len(hits) > 0 {
350				cats["unexpected-carrier"] = true
351			}
352			if hasAdmission {
353				cats["unexpected-admission"] = true
354			}
355		}
356		// Profile text anywhere the expectation does not put it.
357		expJSON, _ := json.Marshal(expected)
358		for _, s := range oq3AllSentinels {
359			if strings.Count(string(obsJSON), s) > strings.Count(string(expJSON), s) {
360				cats["leaked"] = true
361				notes = append(notes, "sentinel "+s)
362			}
363		}
364		// Everything outside the leading message must equal the expectation (history, tools, options).
365		obsRest, expRest := oq3WithoutLeadingSystem(observed), oq3WithoutLeadingSystem(expected)
366		if !reflect.DeepEqual(obsRest, expRest) {
367			cats["request-changed"] = true
368			notes = append(notes, oq3FirstDifference(obsRest, expRest))
369		}
370		if len(cats) == 0 {
371			// Differs, but in a way none of the named checks isolates (for example the leading
372			// message's role or an extra field on it).
373			cats["other"] = true
374		}
375		out := make([]string, 0, len(cats))
376		for c := range cats {
377			out = append(out, c)
378		}
379		sort.Strings(out)
380		return oq3DeliveryVerdict{Correct: false, Categories: out, Detail: strings.Join(notes, "; ")}
381	}
382	
383	func oq3WithoutLeadingSystem(req any) any {
384		c := oq3DeepCopy(req)
385		m, ok := c.(map[string]any)
386		if !ok {
387			return c
388		}
389		delete(m, "admission")
390		msgs, _ := m["messages"].([]any)
391		if len(msgs) > 0 {
392			if first, ok := msgs[0].(map[string]any); ok && oq3Str(first, "role") == "system" {
393				msgs = msgs[1:]
394			}
395		}
396		m["messages"] = msgs
397		return m
398	}
399	
400	// oq3FirstDifference names the first top-level field (or message index) that differs.
401	func oq3FirstDifference(a, b any) string {
402		am, _ := a.(map[string]any)
403		bm, _ := b.(map[string]any)
404		keys := map[string]bool{}
405		for k := range am {
406			keys[k] = true
407		}
408		for k := range bm {
409			keys[k] = true
410		}
411		var ks []string
412		for k := range keys {
413			ks = append(ks, k)
414		}
415		sort.Strings(ks)
416		for _, k := range ks {
417			if !reflect.DeepEqual(am[k], bm[k]) {
418				if k == "messages" {
419					amsg, _ := am[k].([]any)
420					bmsg, _ := bm[k].([]any)
421					if len(amsg) != len(bmsg) {
422						return fmt.Sprintf("messages: %d observed, %d expected", len(amsg), len(bmsg))
423					}
424					for i := range amsg {
425						if !reflect.DeepEqual(amsg[i], bmsg[i]) {
426							return fmt.Sprintf("messages[%d] differs", i)
427						}
428					}
429				}
430				return "field " + k + " differs"
431			}
432		}
433		return "no top-level difference found"
434	}
435	
436	// oq3CheckSummariser is the separate expectation for a compaction summariser request (Q2): it keeps
437	// the compactor's own system prompt, and carries no carrier header and no profile text, so the
438	// carrier was neither injected into it nor stored in the history it summarises.
439	func oq3CheckSummariser(observed any) oq3DeliveryVerdict {
440		msgs := oq3Messages(observed)
441		var cats []string
442		if len(msgs) == 0 || oq3Str(msgs[0], "role") != "system" || !strings.HasPrefix(oq3Str(msgs[0], "content"), oq3CompactionSystemPrefix) {
443			cats = append(cats, "summariser-prompt-replaced")
444		}
445		b, _ := json.Marshal(observed)
446		if oq3HeaderRE.Match(b) || bytes.Contains(b, []byte("User-configured instructions")) {
447			cats = append(cats, "summariser-carries-header")
448		}
449		for _, s := range oq3AllSentinels {
450			if bytes.Contains(b, []byte(s)) {
451				cats = append(cats, "summariser-carries-profile")
452				break
453			}
454		}
455		return oq3DeliveryVerdict{Correct: len(cats) == 0, Categories: cats}
456	}

