 76	func TestOQ3FailureNumber(t *testing.T) {
 77		evidence := os.Getenv("OQ3_EVIDENCE_DIR")
 78		goldens := os.Getenv("OQ3_GOLDENS")
 79		mode := os.Getenv("OQ3_MODE")
 80		if evidence == "" || goldens == "" || (mode != "baseline" && mode != "accept") {
 81			t.Fatalf("OQ3_EVIDENCE_DIR, OQ3_GOLDENS and OQ3_MODE (baseline|accept) are required")
 82		}
 83		freeze := os.Getenv("OQ3_FREEZE") == "1"
 84		if freeze && mode != "baseline" {
 85			t.Fatalf("goldens may only be frozen by a baseline run")
 86		}
 87		source := os.Getenv("OQ3_SOURCE")
 88		all := oq3AllScenarios()
 89		selected, err := oq3Select(all, os.Getenv("OQ3_SCENARIOS"))
 90		if err != nil {
 91			t.Fatal(err)
 92		}
 93		ledgerSHA, ledgerJSON := oq3LedgerSHA(all)
 94		if err := os.MkdirAll(evidence, 0o755); err != nil {
 95			t.Fatal(err)
 96		}
 97		if err := os.WriteFile(filepath.Join(evidence, "ledger.json"), ledgerJSON, 0o644); err != nil {
 98			t.Fatal(err)
 99		}
100		t.Logf("OQ3 ledger sha256 %s (%d scenarios), selected %d", ledgerSHA, len(all), len(selected))
101	
102		var results []oq3ScenarioResult
103		var refResults []oq3ScenarioResult
104		for _, sc := range selected {
105			start := time.Now()
106			d := oq3StartDaemon(t)
107			d.noCapability = sc.NoCapability
108			s := oq3NewSandbox(t, sc.ID)
109			run := oq3NewRun(t, sc, d, s)
110			if strings.HasPrefix(sc.ID, "E") {
111				if bin := os.Getenv("OQ3_BINARY"); bin != "" {
112					run.builtBinary = []string{bin}
113				}
114			}
115			run.execute()
116			res := run.score(goldens, freeze, source)
117			results = append(results, res)
118			if err := oq3WriteJSON(filepath.Join(evidence, "scenarios", sc.ID+".json"), res); err != nil {
119				t.Fatal(err)
120			}
121			// Reference arm (Q7 b): the expected requests, sent through real HTTP to a fresh fake daemon
122			// under the same labels, must all score correct. Kept outside the candidate's numbers.
123			ref := oq3ReferenceArm(t, run, res, goldens)
124			refResults = append(refResults, ref)
125			if err := oq3WriteJSON(filepath.Join(evidence, "reference", sc.ID+".json"), ref); err != nil {
126				t.Fatal(err)
127			}
128			t.Logf("OQ3 scenario %s done in %s: %d deliveries recorded, %d invalid", sc.ID, time.Since(start).Round(time.Millisecond), len(res.Deliveries), len(res.Invalid))
129		}
130	
131		sum := oq3Summarise(results, mode, source, ledgerSHA)
132		if problems := oq3Completeness(selected, results); len(problems) > 0 {
133			sum.Valid = false
134			sum.Invalid = append(sum.Invalid, problems...)
135		}
136		refSum := oq3Summarise(refResults, "reference", "expected requests sent by the reference arm", ledgerSHA)
137		if refSum.FailureNumerator != 0 || refSum.ObservedDeliveries == 0 {
138			sum.Valid = false
139			sum.Invalid = append(sum.Invalid, fmt.Sprintf("reference arm did not read correct deliveries as correct: %d bad or missing of %d", refSum.FailureNumerator, refSum.ObservedDeliveries))
140		}
141		if err := oq3WriteJSON(filepath.Join(evidence, "summary.json"), sum); err != nil {
142			t.Fatal(err)
143		}
144		if err := oq3WriteJSON(filepath.Join(evidence, "reference-summary.json"), refSum); err != nil {
145			t.Fatal(err)
146		}
147		t.Logf("OQ3_FAILURE_NUMBER=%s valid=%v observed=%d bad=%d missing=%d trials=%d", sum.FailureNumber, sum.Valid, sum.ObservedDeliveries, sum.BadObserved, sum.MissingRequired, sum.Trials)
148		t.Logf("OQ3_REFERENCE_ARM=%s observed=%d", refSum.FailureNumber, refSum.ObservedDeliveries)
149		if !sum.Valid {
150			t.Fatalf("OQ3 run is not valid: %s", strings.Join(sum.Invalid, " | "))
151		}
152		t.Logf("OQ3_AUXILIARY bad=%d refusals_held=%d", sum.AuxiliaryBad, sum.RefusalsHeld)
153		if mode == "accept" {
154			// The failure-number component of G1's combined gate (blueprint §10, G1-R-18): necessary,
155			// not sufficient (review finding 14).
156			if sum.FailureNumerator != 0 {
157				t.Fatalf("OQ3 acceptance: failure number %s", sum.FailureNumber)
158			}
159			if sum.AuxiliaryBad != 0 {
160				t.Fatalf("OQ3 acceptance: %d auxiliary failures: %s", sum.AuxiliaryBad, strings.Join(sum.AuxiliaryBadList, " | "))
161			}
162			// Operations pass on their own evidence (saves: response and committed store; reloads:
163			// response). The existing terminal commands report "done" and the /instructions commands
164			// "no-error-seen"; the deliveries after them decide. "absent" and "fail" fail.
165			for k, n := range sum.OperationVerdicts {
166				if !strings.HasSuffix(k, ":pass") && k != "terminal-slash:done" && k != "terminal-slash:no-error-seen" {
167					t.Fatalf("OQ3 acceptance: operation verdict %s x%d", k, n)
168				}
169			}
170			// A terminal refusal during a held turn is judged by that turn's continuation (a delivery).
171			for k, n := range sum.RefusalVerdicts {
172				if !strings.HasSuffix(k, ":pass") && k != "terminal-slash:sent-while-running" {
173					t.Fatalf("OQ3 acceptance: required refusal %s x%d", k, n)
174				}
175			}
176		}
177	}
