179	// oq3ReferenceArm sends, for every delivery the candidate was scored on, the request a correct G1
180	// implementation would send (the oracle's expectation), through real HTTP to a fresh fake daemon,
181	// and scores the captures with the same scorer. A correct delivery must read as correct.
182	func oq3ReferenceArm(t *testing.T, run *oq3Run, res oq3ScenarioResult, goldens string) oq3ScenarioResult {
183		rd := oq3StartDaemon(t)
184		for _, dl := range res.Deliveries {
185			if dl.Expect == nil || dl.Golden == "" {
186				continue
187			}
188			golden, err := oq3LoadGolden(dl.Golden)
189			if err != nil {
190				continue
191			}
192			exp, err := oq3Transform(golden, *dl.Expect, func(model string) (string, bool) {
193				s, ok := rd.modelSystems[oq3ModelBase(model)]
194				return s, ok
195			})
196			if err != nil {
197				continue
198			}
199			body, err := oq3MarshalCanonical(exp)
200			if err != nil {
201				t.Fatal(err)
202			}
203			rd.setLabel(dl.Label)
204			resp, err := http.Post(rd.srv.URL+"/api/chat", "application/json", bytes.NewReader(body))
205			if err != nil {
206				t.Fatalf("reference arm post: %v", err)
207			}
208			resp.Body.Close()
209		}
210		refRun := oq3NewRun(t, run.sc, rd, run.s)
211		// The reference arm reuses the scenario's steps for attribution; its captures are the expected
212		// requests. Summariser requests are not re-sent, so compaction-demonstration checks do not apply.
213		scored := refRun.scoreDeliveriesOnly(goldens)
214		return scored
215	}

 850				if k == 0 {
 851					// A state-changing step must have reached its declared state in the pre-G1 request
 852					// (review finding 5); checked on the golden, which is what every later run is held to.
 853					if problem := oq3AssertState(golden, st.Args); problem != "" {
 854						res.Invalid = append(res.Invalid, fmt.Sprintf("%s: declared state not reached: %s", label, problem))
 855					}
 856				}
 857				exp, terr := oq3Transform(golden, *d.Expect, func(model string) (string, bool) {
 858					s, ok := r.d.modelSystems[oq3ModelBase(model)]
 859					return s, ok
 860				})
 861				if terr != nil {
 862					d.Status = "bad"
 863					d.Verdict = oq3DeliveryVerdict{Categories: []string{"oracle-unresolved"}, Detail: terr.Error()}
 864					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: %v", label, terr))
 865					res.Deliveries = append(res.Deliveries, d)
 866					continue
 867				}
 868				d.Verdict = oq3Score(obs, exp, *d.Expect)
 869				d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
 870				res.Deliveries = append(res.Deliveries, d)
 871			}
 872		}
 873		// Unknown labels, and a leak scan over every other capture on every path (review finding 4).
 874		for _, c := range caps {
 875			if !known[c.Label] {
 876				res.Invalid = append(res.Invalid, fmt.Sprintf("request %d (%s %s) under unknown label %q", c.Seq, c.Method, c.Path, c.Label))
 877				continue
 878			}
 879			if scoredSeq[c.Seq] || (c.Path == "/api/chat" && c.Response == "summary") || c.Path == "/api/generate" {
 880				continue
 881			}
 882			raw := string(c.Body) + c.RawBody
 883			leaked := strings.Contains(raw, "User-configured instructions")
 884			for _, s := range oq3AllSentinels {
 885				leaked = leaked || strings.Contains(raw, s)
 886			}
 887			if leaked {
 888				aux(oq3Delivery{Scenario: r.sc.ID, Label: c.Label, Seq: c.Seq, Kind: "leak-scan", Status: "bad",
 889					Verdict: oq3DeliveryVerdict{Categories: []string{"carries-instructions"}, Detail: c.Method + " " + c.Path}})
 890			}
 891		}
 892		// Compaction must be demonstrable at the request boundary: the first request after a compaction
 893		// step carries the summariser's text in its history.
 894		for i, st := range r.sc.Steps {
 895			if st.Summarisers == 0 || st.Op != "terminal-slash" || notRun[i] {
 896				continue
 897			}
 898			for j := i + 1; j < len(r.sc.Steps); j++ {
 899				if r.sc.Steps[j].Class != "required-dispatch" {
 900					continue
 901				}
 902				nl := oq3Label(r.sc.ID, j, r.sc.Steps[j].Op)
 903				cs := byKey[key{nl, "/api/chat"}]
 904				if len(cs) == 0 || !strings.Contains(string(cs[0].Body), "OQ3-SUMMARY") {
 905					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: the next request (%s) does not carry the compacted history", oq3Label(r.sc.ID, i, st.Op), nl))
 906				}
 907				break
 908			}
 909		}
 910		if len(res.NotMeasured) > 0 {
 911			res.Invalid = append(res.Invalid, fmt.Sprintf("%d steps not measured after a harness failure", len(res.NotMeasured)))
 912		}
 913		return res
 914	}
