 916	// oq3AssertState checks a golden (a pre-G1 request) against the state its step declares:
 917	// assert_tools ("0" or "some"), assert_model, assert_system ("absent" or "present").
 918	func oq3AssertState(golden any, args map[string]string) string {
 919		m, _ := golden.(map[string]any)
 920		if want := args["assert_tools"]; want != "" {
 921			tools, _ := m["tools"].([]any)
 922			if (want == "0") != (len(tools) == 0) {
 923				return fmt.Sprintf("tools: want %s, request has %d", want, len(tools))
 924			}
 925		}
 926		if want := args["assert_model"]; want != "" {
 927			if got, _ := m["model"].(string); oq3ModelBase(got) != want {
 928				return fmt.Sprintf("model: want %s, request has %s", want, got)
 929			}
 930		}
 931		if want := args["assert_system"]; want != "" {
 932			msgs := oq3Messages(golden)
 933			has := len(msgs) > 0 && oq3Str(msgs[0], "role") == "system"
 934			if (want == "present") != has {
 935				return fmt.Sprintf("system message: want %s", want)
 936			}
 937		}
 938		return ""
 939	}
