 941	// scoreDeliveriesOnly scores the requests captured under each dispatch step against that step's
 942	// expectations and the frozen goldens, without freezing and without the omission, summariser and
 943	// compaction checks. The reference arm uses it: it only re-sends requests that have a golden.
 944	func (r *oq3Run) scoreDeliveriesOnly(goldenDir string) oq3ScenarioResult {
 945		res := oq3ScenarioResult{Scenario: r.sc, Sandbox: r.s.root}
 946		caps := r.d.snapshot()
 947		res.Captures = caps
 948		for i, st := range r.sc.Steps {
 949			if st.Class != "required-dispatch" {
 950				continue
 951			}
 952			label := oq3Label(r.sc.ID, i, st.Op)
 953			k := 0
 954			for _, c := range caps {
 955				if c.Path != "/api/chat" || c.Label != label {
 956					continue
 957				}
 958				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k, Seq: c.Seq}
 959				if k >= len(st.Expect) {
 960					d.Status, d.Verdict = "unexpected", oq3DeliveryVerdict{Categories: []string{"unexpected-request"}}
 961					res.Deliveries = append(res.Deliveries, d)
 962					k++
 963					continue
 964				}
 965				e := st.Expect[k]
 966				d.Expect = &e
 967				gp := oq3GoldenPath(goldenDir, r.sc.ID, i, k)
 968				d.Golden = gp
 969				k++
 970				obs, err := oq3Normalise(c.Body, r.s.root)
 971				if err != nil {
 972					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}}
 973					res.Deliveries = append(res.Deliveries, d)
 974					continue
 975				}
 976				golden, err := oq3LoadGolden(gp)
 977				if err != nil {
 978					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"no-golden"}}
 979					res.Deliveries = append(res.Deliveries, d)
 980					continue
 981				}
 982				exp, err := oq3Transform(golden, e, func(model string) (string, bool) {
 983					s, ok := r.d.modelSystems[oq3ModelBase(model)]
 984					return s, ok
 985				})
 986				if err != nil {
 987					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"oracle-unresolved"}}
 988					res.Deliveries = append(res.Deliveries, d)
 989					continue
 990				}
 991				d.Verdict = oq3Score(obs, exp, e)
 992				d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
 993				res.Deliveries = append(res.Deliveries, d)
 994			}
 995		}
 996		return res
 997	}
