1031	type oq3Summary struct {
1032		Mode                  string         `json:"mode"`
1033		Source                string         `json:"source"`
1034		Trials                int            `json:"controlled_conversation_trials"`
1035		ObservedDeliveries    int            `json:"observed_deliveries"`
1036		BadObserved           int            `json:"bad_observed_deliveries"`
1037		MissingRequired       int            `json:"missing_required_deliveries"`
1038		Unexpected            int            `json:"unexpected_requests"`
1039		FailureNumber         string         `json:"failure_number"`
1040		FailureNumerator      int            `json:"failure_numerator"`
1041		CategoryCounts        map[string]int `json:"category_counts_overlapping"`
1042		PerFamily             map[string]any `json:"per_family"`
1043		PerTrial              map[string]any `json:"per_trial"`
1044		OperationVerdicts     map[string]int `json:"operation_verdicts"`
1045		RefusalVerdicts       map[string]int `json:"required_refusal_verdicts"`
1046		AuxiliaryChecks       map[string]int `json:"auxiliary_checks"`
1047		AuxiliaryBad          int            `json:"auxiliary_bad"`
1048		AuxiliaryBadList      []string       `json:"auxiliary_bad_list,omitempty"`
1049		RefusalsHeld          int            `json:"required_refusals_held"`
1050		NotMeasured           []string       `json:"not_measured,omitempty"`
1051		Valid                 bool           `json:"valid"`
1052		Invalid               []string       `json:"invalid,omitempty"`
1053		ScenariosRun          []string       `json:"scenarios_run"`
1054		LedgerSHA256          string         `json:"ledger_sha256"`
1055	}
