1057	func oq3Summarise(results []oq3ScenarioResult, mode, source, ledgerSHA string) oq3Summary {
1058		s := oq3Summary{Mode: mode, Source: source, CategoryCounts: map[string]int{}, PerFamily: map[string]any{}, PerTrial: map[string]any{},
1059			OperationVerdicts: map[string]int{}, RefusalVerdicts: map[string]int{}, AuxiliaryChecks: map[string]int{}, LedgerSHA256: ledgerSHA, Valid: true}
1060		family := map[string]string{}
1061		type tally struct{ Observed, Bad, Missing, Correct int }
1062		trialT := map[string]*tally{}
1063		for _, r := range results {
1064			s.ScenariosRun = append(s.ScenariosRun, r.Scenario.ID)
1065			for _, tr := range r.Scenario.Trials {
1066				family[tr.ID] = tr.Family
1067				trialT[tr.ID] = &tally{}
1068				s.Trials++
1069			}
1070			for _, d := range r.Deliveries {
1071				t := trialT[d.Trial]
1072				switch d.Status {
1073				case "correct":
1074					s.ObservedDeliveries++
1075					t.Observed++
1076					t.Correct++
1077				case "bad":
1078					s.ObservedDeliveries++
1079					s.BadObserved++
1080					t.Observed++
1081					t.Bad++
1082				case "missing":
1083					s.MissingRequired++
1084					t.Missing++
1085				case "unexpected":
1086					s.ObservedDeliveries++
1087					s.Unexpected++
1088					s.BadObserved++
1089					t.Observed++
1090					t.Bad++
1091				case "refused-as-required":
1092					s.RefusalsHeld++
1093				}
1094				for _, c := range d.Verdict.Categories {
1095					s.CategoryCounts[c]++
1096				}
1097			}
1098			for _, a := range r.Auxiliary {
1099				s.AuxiliaryChecks[a.Kind+":"+a.Status]++
1100				if a.Status != "correct" {
1101					s.AuxiliaryBad++
1102					s.AuxiliaryBadList = append(s.AuxiliaryBadList, fmt.Sprintf("%s %s %v", a.Label, a.Kind, a.Verdict.Categories))
1103				}
1104			}
1105			s.NotMeasured = append(s.NotMeasured, r.NotMeasured...)
1106			for _, e := range r.Events {
1107				switch e.Class {
1108				case "operation":
1109					s.OperationVerdicts[e.Op+":"+e.Verdict]++
1110				case "required-refusal":
1111					s.RefusalVerdicts[e.Op+":"+e.Verdict]++
1112				}
1113			}
1114			if len(r.Invalid) > 0 {
1115				s.Valid = false
1116				s.Invalid = append(s.Invalid, r.Invalid...)
1117			}
1118		}
1119		fam := map[string]*tally{}
1120		for id, t := range trialT {
1121			f := family[id]
1122			if fam[f] == nil {
1123				fam[f] = &tally{}
1124			}
1125			fam[f].Observed += t.Observed
1126			fam[f].Bad += t.Bad
1127			fam[f].Missing += t.Missing
1128			fam[f].Correct += t.Correct
1129			s.PerTrial[id] = map[string]any{"family": f, "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing}
1130		}
1131		famTrials := map[string]int{}
1132		for _, f := range family {
1133			famTrials[f]++
1134		}
1135		for f, t := range fam {
1136			s.PerFamily[f] = map[string]any{"trials": famTrials[f], "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing,
1137				"failure_number": oq3Ratio(t.Bad+t.Missing, famTrials[f])}
1138		}
1139		s.FailureNumerator = s.BadObserved + s.MissingRequired
1140		s.FailureNumber = oq3Ratio(s.FailureNumerator, s.Trials)
1141		return s
1142	}
