1144	// oq3Ratio prints an exact fraction and a decimal; a zero denominator is refused, never printed as zero.
1145	func oq3Ratio(num, den int) string {
1146		if den == 0 {
1147			return "undefined (no trials)"
1148		}
1149		return fmt.Sprintf("%d/%d = %.4f", num, den, float64(num)/float64(den))
1150	}
