1152	func oq3LedgerSHA(scs []oq3Scenario) (string, []byte) {
1153		b, _ := json.MarshalIndent(scs, "", "  ")
1154		sum := sha256.Sum256(b)
1155		return hex.EncodeToString(sum[:]), b
1156	}
