619	func oq3StartDesktopWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, life int) *oq3Desktop {
620		token := fmt.Sprintf("oq3-token-%d-%d", time.Now().UnixNano(), life)
621		portFile := filepath.Join(s.tmp, fmt.Sprintf("desktop-%d.port", life))
622		c := oq3HelperCmd(s, d, "desktop", "OQ3_TOKEN="+token, "OQ3_PORT_FILE="+portFile,
623			"OQ3_LOG_FILE="+filepath.Join(s.logs, fmt.Sprintf("desktop-%d.log", life)))
624		var stderr bytes.Buffer
625		c.Stderr = &stderr
626		c.Stdout = &stderr
627		if err := c.Start(); err != nil {
628			fail("start desktop: %v", err)
629		}
630		p := &oq3Desktop{fail: fail, cmd: c, token: token, stderr: &stderr, exited: make(chan error, 1)}
631		go func() { p.exited <- c.Wait() }()
632		var port []byte
633		if !oq3WaitFor(20*time.Second, func() bool {
634			b, err := os.ReadFile(portFile)
635			if err == nil && len(b) > 0 {
636				port = b
637				return true
638			}
639			return false
640		}) {
641			_ = c.Process.Kill()
642			fail("desktop process %d never published its port; stderr=%s", life, stderr.String())
643		}
644		p.base = "http://127.0.0.1:" + string(port)
645		return p
646	}
