648	// stop ends the desktop process the way the operator quitting does (SIGTERM) and waits for it, so
649	// that a later lifetime can only have read what the earlier one persisted.
650	func (p *oq3Desktop) stop() {
651		if err := p.stopNoFatal(); err != nil {
652			p.fail("%v", err)
653		}
