656	func (p *oq3Desktop) stopNoFatal() error {
657		_ = p.cmd.Process.Signal(syscall.SIGTERM)
658		select {
659		case err := <-p.exited:
660			if err != nil {
661				return fmt.Errorf("desktop process exit: %v; output=%s", err, p.stderr.String())
662			}
663			return nil
664		case <-time.After(15 * time.Second):
665			_ = p.cmd.Process.Kill()
666			return fmt.Errorf("desktop process did not exit on SIGTERM")
667		}
668	}
