670	type oq3HTTPResult struct {
671		Status      int    `json:"status"`
672		ContentType string `json:"content_type"`
673		Body        string `json:"body"`
674		Error       string `json:"transport_error,omitempty"`
675	}
676	
677	func (p *oq3Desktop) do(method, path string, body any) oq3HTTPResult {
678		return p.doAuth(method, path, body, true)
679	}
680	
681	// doAuth never fails the test: a transport error is returned in the result (status -1), so it is
682	// safe from any goroutine; callers decide whether it is a harness failure.
683	func (p *oq3Desktop) doAuth(method, path string, body any, auth bool) oq3HTTPResult {
684		var rd io.Reader
685		if body != nil {
686			b, err := json.Marshal(body)
687			if err != nil {
688				return oq3HTTPResult{Status: -1, Error: err.Error()}
689			}
690			rd = bytes.NewReader(b)
691		}
692		req, err := http.NewRequest(method, p.base+path, rd)
693		if err != nil {
694			return oq3HTTPResult{Status: -1, Error: err.Error()}
695		}
696		req.Header.Set("Content-Type", "application/json")
697		if auth {
698			req.AddCookie(&http.Cookie{Name: "token", Value: p.token})
699		}
700		resp, err := (&http.Client{Timeout: 90 * time.Second}).Do(req)
701		if err != nil {
702			return oq3HTTPResult{Status: -1, Error: err.Error()}
703		}
704		defer resp.Body.Close()
705		data, _ := io.ReadAll(resp.Body)
706		return oq3HTTPResult{Status: resp.StatusCode, ContentType: resp.Header.Get("Content-Type"), Body: string(data)}
707	}
