714	// chatBody sends one turn and returns the chat id the stream reports.
715	func (p *oq3Desktop) chatBody(id string, body map[string]any) (string, oq3HTTPResult) {
716		res := p.do(http.MethodPost, "/api/v1/chat/"+id, body)
717		chatID := id
718		sc := bufio.NewScanner(strings.NewReader(res.Body))
719		sc.Buffer(make([]byte, 1<<20), 1<<20)
720		for sc.Scan() {
721			var ev struct {
722				EventName string  `json:"eventName"`
723				ChatID    *string `json:"chatId"`
724			}
725			if json.Unmarshal(sc.Bytes(), &ev) == nil && ev.ChatID != nil && *ev.ChatID != "" {
726				chatID = *ev.ChatID
727			}
728		}
729		return chatID, res
730	}
