759	// oq3StartTerminalWith starts either the launch-function helper (argv nil) or a given program
760	// (the built binary for the entry arm) on a fresh pseudo-terminal.
761	func oq3StartTerminalWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, session, model string, argv []string) *oq3Terminal {
762		master, slave, err := oq3OpenPTY()
763		if err != nil {
764			fail("pty: %v", err)
765		}
766		var c *exec.Cmd
767		if argv == nil {
768			c = oq3HelperCmd(s, d, "terminal", "OQ3_MODEL="+model)
769		} else {
770			c = exec.Command(argv[0], argv[1:]...)
771			c.Dir = s.work
772			c.Env = s.env(d.srv.URL)
773		}
774		c.Stdin, c.Stdout, c.Stderr = slave, slave, slave
775		c.SysProcAttr = &syscall.SysProcAttr{Setsid: true, Setctty: true, Ctty: 0}
776		if err := c.Start(); err != nil {
777			fail("start terminal: %v", err)
778		}
779		slave.Close()
780		p := &oq3Terminal{fail: fail, cmd: c, master: master, exited: make(chan error, 1)}
781		go p.readLoop(filepath.Join(s.logs, "terminal-"+session+".raw"))
782		go func() {
783			err := c.Wait()
784			p.mu.Lock()
785			p.gone = true
786			p.mu.Unlock()
787			p.exited <- err
788		}()
789		return p
790	}
