829	// readLoop keeps the transcript and answers the terminal queries a real emulator would answer
830	// (background colour, foreground colour, cursor position, device attributes).
831	func (p *oq3Terminal) readLoop(rawPath string) {
832		f, _ := os.Create(rawPath)
833		defer func() {
834			if f != nil {
835				f.Close()
836			}
837		}()
838		buf := make([]byte, 64*1024)
839		for {
840			n, err := p.master.Read(buf)
841			if n > 0 {
842				chunk := buf[:n]
843				if f != nil {
844					f.Write(chunk)
845				}
846				p.mu.Lock()
847				p.raw.Write(chunk)
848				p.mu.Unlock()
849				s := string(chunk)
850				if strings.Contains(s, "\x1b]11;?") {
851					p.master.Write([]byte("\x1b]11;rgb:1c1c/1c1c/1c1c\x1b\\"))
852				}
853				if strings.Contains(s, "\x1b]10;?") {
854					p.master.Write([]byte("\x1b]10;rgb:e0e0/e0e0/e0e0\x1b\\"))
855				}
856				if strings.Contains(s, "\x1b[6n") {
857					p.master.Write([]byte("\x1b[1;1R"))
858				}
859				if strings.Contains(s, "\x1b[c") || strings.Contains(s, "\x1b[0c") {
860					p.master.Write([]byte("\x1b[?62;22c"))
861				}
862			}
863			if err != nil {
864				return
865			}
866		}
867	}
