881	// quiet waits until the program has produced no output for the given interval.
882	func (p *oq3Terminal) quiet(interval, timeout time.Duration) bool {
883		deadline := time.Now().Add(timeout)
884		last := p.rawLen()
885		lastChange := time.Now()
886		for time.Now().Before(deadline) {
887			time.Sleep(25 * time.Millisecond)
888			if n := p.rawLen(); n != last {
889				last, lastChange = n, time.Now()
890				continue
891			}
892			if time.Since(lastChange) >= interval {
893				return true
894			}
895		}
896		return false
897	}
