961	// oq3RunCLIWith runs one CLI invocation: the root command in a re-executed helper process, or the
962	// built binary when one is given (the entry arm).
963	func oq3RunCLIWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, binary []string, args ...string) oq3CLIResult {
964		var c *exec.Cmd
965		if binary == nil {
966			a, _ := json.Marshal(args)
967			c = oq3HelperCmd(s, d, "cli", "OQ3_ARGS="+string(a))
968		} else {
969			c = exec.Command(binary[0], append(append([]string{}, binary[1:]...), args...)...)
970			c.Dir = s.work
971			c.Env = s.env(d.srv.URL)
972		}
973		out, err := c.CombinedOutput()
974		code := 0
975		if err != nil {
976			var ee *exec.ExitError
977			if !errors.As(err, &ee) {
978				fail("cli %v: %v", args, err)
979			}
980			code = ee.ExitCode()
981		}
982		return oq3CLIResult{Args: args, ExitCode: code, Output: string(out)}
983	}

