 39		hA11 := "User-configured instructions; revision 1; selection 1:\n"
 40		hB23 := "User-configured instructions; revision 2; selection 3:\n"
 41	
 42		desktopGolden := `{"model":"oq3-model","messages":[{"role":"user","content":"Hello."}],"stream":true,"options":null}`
 43		desktopExpected := `{"model":"oq3-model","messages":[{"role":"system","content":` + oq3JSONString(ms1+"\n\n"+hA11+A) + `},{"role":"user","content":"Hello."}],"stream":true,"options":null,"admission":{"version":1}}`
 44		terminalGolden := `{"model":"oq3-model","messages":[{"role":"system","content":"BASE PROMPT"},{"role":"user","content":"Hi."}],"options":{}}`
 45		terminalExpected := `{"model":"oq3-model","messages":[{"role":"system","content":` + oq3JSONString("BASE PROMPT\n\n"+hB23+B) + `},{"role":"user","content":"Hi."}],"options":{},"admission":{"version":1}}`
 46		terminalOffGolden := `{"model":"oq3-model","messages":[{"role":"user","content":"Hi."}],"options":{}}`
 47		terminalOffExpected := `{"model":"oq3-model","messages":[{"role":"system","content":` + oq3JSONString(hA11+A) + `},{"role":"user","content":"Hi."}],"options":{},"admission":{"version":1}}`
 48	
 49		ms := func(model string) (string, bool) {
 50			if model == "oq3-model" {
 51				return ms1, true
 52			}
 53			return "", false
 54		}
 55		eD := cD(1, 1, "A")
 56		eT := cT(2, 3, "B")
 57		eTOff := cT(1, 1, "A")
 58	
 59		// 1. The transform matches the hand-written expectation in all three shapes.
 60		for _, c := range []struct {
 61			name, golden, expected string
 62			e                      oq3Expect
 63		}{{"desktop", desktopGolden, desktopExpected, eD}, {"terminal", terminalGolden, terminalExpected, eT}, {"terminal-system-off", terminalOffGolden, terminalOffExpected, eTOff}} {
 64			got, err := oq3Transform(oq3MustNorm(t, c.golden), c.e, ms)
 65			if err != nil {
