194	func TestOQ3RunnerControls(t *testing.T) {
195		all := oq3AllScenarios()
196		// Empty and unknown selections are refused.
197		if _, err := oq3Select(all, ""); err == nil {
198			t.Fatal("empty selection accepted")
199		}
200		if _, err := oq3Select(all, "D1,NOPE"); err == nil {
201			t.Fatal("unknown scenario accepted")
202		}
203		// Frozen trial identities are unique across the ledger.
204		seen := map[string]bool{}
205		ids := []string{}
206		for _, sc := range all {
207			for _, tr := range sc.Trials {
208				if seen[tr.ID] {
209					t.Fatalf("duplicate trial %s", tr.ID)
210				}
211				seen[tr.ID] = true
212				ids = append(ids, tr.ID)
213			}
214			for i, st := range sc.Steps {
215				if st.Class == "required-dispatch" && (st.Trial == "" || !seen[st.Trial] && !oq3TrialIn(sc, st.Trial)) {
216					t.Fatalf("%s step %d dispatches for an undeclared trial %q", sc.ID, i, st.Trial)
217				}
218			}
219		}
220		sort.Strings(ids)
221		t.Logf("ledger: %d scenarios, %d trials", len(all), len(ids))
222	
223		// A missing trial is caught by the completeness check.
224		sel, _ := oq3Select(all, "D1")
225		if p := oq3Completeness(sel, []oq3ScenarioResult{{Scenario: sel[0]}}); len(p) == 0 {
226			t.Fatal("a trial with no delivery record passed completeness")
227		}
228		if p := oq3Completeness(sel, nil); len(p) == 0 {
229			t.Fatal("a scenario with no result passed completeness")
230		}
231	
232		goldens := t.TempDir()
233		// Auxiliary faults (review findings 2-4): each must be reported as an auxiliary failure, which
234		// gates acceptance; an unknown inference endpoint must make the run invalid.
235		for _, fault := range []string{"undeclared-summariser", "leak-in-metadata", "unknown-endpoint"} {
236			d := oq3StartDaemon(t)
237			s := oq3NewSandbox(t, "AUX-"+fault)
238			sc := oq3Scenario{ID: "AUX", Trials: []oq3Trial{{"AUX-X", famSave, "desktop", ""}},
239				Steps: []oq3Step{h("desktop-start"), dTurn("AUX-X", "X", "OQ3 auxiliary control turn.", nD()), h("desktop-stop")}}
240			run := oq3NewRun(t, sc, d, s)
241			run.execute()
242			d.setLabel(oq3Label("AUX", 1, "desktop-turn"))
243			switch fault {
244			case "undeclared-summariser":
245				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[{"role":"system","content":"`+oq3CompactionSystemPrefix+` extra"},{"role":"user","content":"archive"}]}`))
246			case "leak-in-metadata":
247				resp, err := http.Post(d.srv.URL+"/api/show", "application/json", strings.NewReader(`{"model":"oq3-model","system":"SENTINEL-A-MID-9e41"}`))
248				if err != nil {
249					t.Fatal(err)
250				}
251				resp.Body.Close()
252			case "unknown-endpoint":
253				resp, err := http.Post(d.srv.URL+"/api/embed", "application/json", strings.NewReader(`{"model":"oq3-model","input":"x"}`))
254				if err != nil {
255					t.Fatal(err)
256				}
257				resp.Body.Close()
258			}
259			res := run.score(goldens, true, "auxiliary control")
260			sum := oq3Summarise([]oq3ScenarioResult{res}, "control", "auxiliary control", "none")
261			switch fault {
262			case "unknown-endpoint":
263				if len(res.Invalid) == 0 {
264					t.Fatalf("an unknown inference endpoint did not make the run invalid")
265				}
266				t.Logf("auxiliary fault %-22s -> invalid: %v", fault, res.Invalid)
267			default:
268				if sum.AuxiliaryBad == 0 {
269					t.Fatalf("auxiliary fault %s was not reported", fault)
270				}
271				t.Logf("auxiliary fault %-22s -> %v", fault, sum.AuxiliaryBadList)
272			}
273		}
274	
275		// Harness faults on a real desktop scenario: each must make the run invalid, not change the number.
276		for _, fault := range []string{"malformed-capture", "extra-request", "unknown-label", "none"} {
277			d := oq3StartDaemon(t)
278			s := oq3NewSandbox(t, "RC-"+fault)
279			sc := oq3Scenario{ID: "RC", Trials: []oq3Trial{{"RC-X", famSave, "desktop", ""}},
280				Steps: []oq3Step{h("desktop-start"), dTurn("RC-X", "X", "OQ3 runner control turn.", nD()), h("desktop-stop")}}
281			run := oq3NewRun(t, sc, d, s)
282			run.execute()
283			label := oq3Label("RC", 1, "desktop-turn")
284			switch fault {
285			case "malformed-capture":
286				d.setLabel(label)
287				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[`))
288			case "extra-request":
289				d.setLabel(label)
290				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[{"role":"user","content":"extra"}]}`))
291			case "unknown-label":
292				d.setLabel("RC/99/nowhere")
293				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[{"role":"user","content":"stray"}]}`))
294			}
295			res := run.score(goldens, true, "runner control")
296			if fault == "none" {
297				if len(res.Invalid) != 0 {
298					t.Fatalf("clean control run invalid: %v", res.Invalid)
299				}
300				continue
301			}
302			if len(res.Invalid) == 0 {
303				t.Fatalf("harness fault %s did not make the run invalid", fault)
304			}
305			t.Logf("harness fault %-18s -> invalid: %v", fault, res.Invalid)
306		}
307	
308		// A failing child: a terminal session for a model the daemon does not have exits at once; the
309		// step is a harness failure and the run is invalid, never a missing delivery.
310		d := oq3StartDaemon(t)
311		s := oq3NewSandbox(t, "RC-child")
312		sc := oq3Scenario{ID: "RCC", Trials: []oq3Trial{{"RCC-X", famSave, "terminal", ""}},
313			Steps: []oq3Step{with(h("terminal-start"), "model", "no-such-model"), tTurn("RCC-X", "OQ3 turn that must not be scored.", nT()), h("terminal-stop")}}
314		run := oq3NewRun(t, sc, d, s)
315		run.execute()
316		res := run.score(goldens, true, "runner control")
317		if len(res.Invalid) == 0 {
318			t.Fatal("a failing child process did not make the run invalid")
319		}
320		// Review finding 12: steps not run after a harness failure are not measured, never missing.
321		if sum := oq3Summarise([]oq3ScenarioResult{res}, "control", "failing child", "none"); sum.FailureNumerator != 0 || len(sum.NotMeasured) == 0 {
322			t.Fatalf("a failing child changed the number: numerator %d, not measured %v", sum.FailureNumerator, sum.NotMeasured)
323		}
324		t.Logf("failing child -> invalid: %v; not measured: %v", res.Invalid, res.NotMeasured)
325	}
