272	func (c *SimpleCompactor) summarizeEmptyFallback(ctx context.Context, req CompactionRequest, previousSummary string, archive []api.Message) (string, error) {
273		retry := req
274		retry.Think = &api.ThinkValue{Value: false}
275		summary, err := c.summarize(ctx, retry, previousSummary, archive)
276		if err == nil {
277			return summary, nil
278		}
279		if !isUnsupportedCompactionThinkError(err) {
280			return "", err
281		}
282		if req.Think == nil {
283			return "", nil
284		}
285		retry.Think = nil
