289	func isUnsupportedCompactionThinkError(err error) bool {
290		if err == nil {
291			return false
292		}
293		text := strings.ToLower(err.Error())
294		if !strings.Contains(text, "think") {
295			return false
296		}
297		var statusErr api.StatusError
298		if errors.As(err, &statusErr) && statusErr.StatusCode != 0 {
299			return statusErr.StatusCode == http.StatusBadRequest
300		}
301		return strings.Contains(text, "does not support") || strings.Contains(text, "not supported") || strings.Contains(text, "unsupported")
302	}
